pub fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

pub fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    // Pre-allocate the output Vec with the exact capacity we need
    let n = x.len();
    let mut result: Vec<f32> = Vec::with_capacity(n);

    // Iterate over the input by index; the loop measure is n - i,
    // which strictly decreases each iteration and ensures termination
    let mut i = 0;
    while i < n {
        // Safe indexing: 0 <= i < n
        let v = x[i];
        result.push(v.log10());
        i += 1;
    }

    // At this point i == n, so result.len() == n == x.len()
    result
}

